// ─── Ajustes ──────────────────────────────────────────────────────────────
// Nada de esto es un secreto: el token del bot va en la credencial de
// Telegram, no aquí.
const AJUSTES = {
  // Usuario del bot, solo para enseñarlo en el panel. Ej: '@bitaxus_ideas_bot'
  BOT: 'PON_AQUI_EL_USUARIO_DE_TU_BOT',
  // Cuántas ideas se guardan. Las más viejas se van cayendo.
  LIMITE: 40,
};

const env = (() => { try { return $env ?? {}; } catch { return {}; } })();
const BOT = env.TELEGRAM_BOT_USERNAME || AJUSTES.BOT;
const LIMITE = Number(env.TELEGRAM_LIMITE_IDEAS || AJUSTES.LIMITE);

// El almacén: datos estáticos del workflow. Sobreviven entre ejecuciones y no
// hacen falta ni base de datos ni fichero. Ojo: dos ejecuciones a la vez leen
// cada una su copia, así que esto vale para una bandeja personal, no para un
// equipo escribiendo en paralelo.
function almacen() {
  const s = $getWorkflowStaticData('global');
  s.ideas = Array.isArray(s.ideas) ? s.ideas : [];
  s.chats = Array.isArray(s.chats) ? s.chats : [];
  if (!s.codigo) s.codigo = nuevoCodigo();
  return s;
}

function nuevoCodigo() {
  // Sin vocales ni caracteres que se confundan al dictarlos por voz.
  const alfabeto = 'BCDFGHJKLMNPQRSTVWXYZ23456789';
  let c = '';
  for (let i = 0; i < 6; i++) c += alfabeto[Math.floor(Math.random() * alfabeto.length)];
  return c;
}

const FORMATOS = {
  instagram: { etiqueta: 'Publicación de Instagram', plataforma: 'instagram' },
  youtube:   { etiqueta: 'Idea de YouTube',          plataforma: 'youtube'   },
  guion:     { etiqueta: 'Ayuda con el guion',       plataforma: 'instagram' },
};

// Órdenes que saltan la pregunta y van directas al formato.
const ATAJOS = { '/ig': 'instagram', '/instagram': 'instagram', '/yt': 'youtube',
                 '/youtube': 'youtube', '/guion': 'guion', '/script': 'guion' };

const s = almacen();
const u = $input.first().json;

// Telegram manda o un mensaje o la pulsación de un botón.
const msg = u.message ?? u.channel_post ?? null;
const cb = u.callback_query ?? null;
const chatId = String(msg?.chat?.id ?? cb?.message?.chat?.id ?? '');
const vinculado = s.chats.includes(chatId);

const base = { chatId, bot: BOT, vinculado, callbackId: cb?.id ?? null };

// ── Botón pulsado: ya sabemos el formato ──────────────────────────────────
if (cb) {
  const [, id, formato] = String(cb.data ?? '').split(':');
  const idea = s.ideas.find((i) => i.id === id);
  if (!vinculado || !idea || !FORMATOS[formato]) {
    return [{ json: { ...base, accion: 'avisar',
      texto: 'Esa idea ya no está en la bandeja. Escríbeme el pensamiento otra vez.' } }];
  }
  return [{ json: { ...base, accion: 'redactar', id, formato,
    etiqueta: FORMATOS[formato].etiqueta, plataforma: FORMATOS[formato].plataforma,
    pensamiento: idea.pensamiento } }];
}

const texto = String(msg?.text ?? '').trim();
if (!texto) {
  return [{ json: { ...base, accion: 'avisar',
    texto: 'De momento solo entiendo texto. Escríbeme el pensamiento y lo convierto.' } }];
}

// ── Vinculación ───────────────────────────────────────────────────────────
if (texto.toLowerCase().startsWith('/vincular')) {
  const codigo = texto.split(/\s+/)[1]?.toUpperCase() ?? '';
  if (codigo !== s.codigo) {
    return [{ json: { ...base, accion: 'avisar',
      texto: 'Ese código no es el que muestra el panel. Ábrelo en Inicio y cópialo tal cual.' } }];
  }
  if (!s.chats.includes(chatId)) s.chats.push(chatId);
  // Se quema el código: quien lo vio por encima del hombro ya no lo puede usar.
  s.codigo = nuevoCodigo();
  return [{ json: { ...base, vinculado: true, accion: 'avisar',
    texto: 'Listo, ya estamos conectados. Escríbeme cualquier pensamiento y te lo convierto en publicación de Instagram, idea de YouTube o guion.' } }];
}

if (!vinculado) {
  return [{ json: { ...base, accion: 'avisar',
    texto: 'Antes de empezar hay que enlazar este chat con tu panel. Abre Bitaxus en Inicio, copia el código y mándamelo así:\n\n/vincular TUCODIGO' } }];
}

if (texto === '/start' || texto === '/ayuda' || texto === '/help') {
  return [{ json: { ...base, accion: 'avisar',
    texto: 'Mándame el pensamiento tal cual te salga y te pregunto en qué lo convierto.\n\nSi ya lo sabes, ve directo:\n/ig  tu pensamiento — pie de Instagram\n/yt  tu pensamiento — idea de YouTube\n/guion tu pensamiento — guion de 30-45 s' } }];
}

// ── Atajo con formato incluido ────────────────────────────────────────────
const orden = texto.split(/\s+/)[0].toLowerCase();
if (ATAJOS[orden]) {
  const pensamiento = texto.slice(orden.length).trim();
  if (!pensamiento) {
    return [{ json: { ...base, accion: 'avisar',
      texto: 'Escribe el pensamiento detrás de la orden. Por ejemplo:\n' + orden + ' los reels de 15 s rinden más que los de 60' } }];
  }
  const formato = ATAJOS[orden];
  const id = 'idea-' + Date.now().toString(36);
  s.ideas.unshift({ id, pensamiento, recibido: new Date().toISOString(), estado: 'nueva' });
  s.ideas = s.ideas.slice(0, LIMITE);
  return [{ json: { ...base, accion: 'redactar', id, formato, pensamiento,
    etiqueta: FORMATOS[formato].etiqueta, plataforma: FORMATOS[formato].plataforma } }];
}

// ── Pensamiento suelto: guardarlo y preguntar ─────────────────────────────
const id = 'idea-' + Date.now().toString(36);
s.ideas.unshift({ id, pensamiento: texto, recibido: new Date().toISOString(), estado: 'nueva' });
s.ideas = s.ideas.slice(0, LIMITE);

return [{ json: { ...base, accion: 'preguntar', id, pensamiento: texto } }];

